import { useEffect, useRef, useState } from "react";
import { clamp, ease } from "./helpers";
import '../index.css'

export default function TrustSection() {
  const sectionRef = useRef(null);
  const [p, setP] = useState(0);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    check();
    window.addEventListener("resize", check, { passive: true });
    return () => window.removeEventListener("resize", check);
  }, []);

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const scrolled = -el.getBoundingClientRect().top;
      const total = el.offsetHeight - window.innerHeight;
      setP(Math.max(0, Math.min(1, scrolled / (total * 0.88))));
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const lp = (start, end) => ease(clamp((p - start) / (end - start), 0, 1));

  // Opacity: fades in over its window
  const ghost1Opacity = lp(0.10, 0.30);
  const ghost2Opacity = lp(0.35, 0.55);

  // Scroll-driven upward travel: starts at +180px (below), ends at -60px (above centre)
  // Linear — directly tied to scroll progress, no easing stop
  const ghost1Y = 180 - p * 340;   // at p=0 → +180px, at p=0.7 → ~-60px
  const ghost2Y = 220 - p * 380;   // offset start so it lags slightly behind

  return (
    <div id="dots-png" ref={sectionRef} className="h-[100vh] sm:h-[280vh]" style={{ position: "relative" }}>
      <div
        className="h-[72vh] sm:h-[100vh]"
        style={{
          position: "sticky", top: 0, height: "100vh",
          display: "flex", flexDirection: "column",
          alignItems: "center", justifyContent: "center",
          overflow: "hidden",
          padding: isMobile ? "0 5vw" : "0 6vw",
        }}
      >

        {/* ── Static big text ─────────────────────────────────────── */}
        <div style={{ position: "relative", textAlign: "center", zIndex: 1, lineHeight: 1.08 }}>
          <div>
            <span className="sm:text-[110px] text-[50px]" style={{
              fontFamily: "'Inter',sans-serif",
              fontWeight: 600, color: "#1A3BB0",
              display: "block", lineHeight: 1.0,
            }}>Trust,</span>
          </div>

          <div style={{ display: "flex", alignItems: "baseline", justifyContent: "center", gap: "0.2em", flexWrap: "wrap" }}>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 300, color: "#5D5D5D", lineHeight: 1.0 }}>
              however is{" "}
            </span>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 700, color: "#343434", lineHeight: 1.05, marginLeft: "14px" }}>
              fragile.
            </span>
          </div>

          <div>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 700, color: "#CE1010" }}>One </span>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 400, color: "#5d5d5d" }}>news headline.</span>
          </div>

          <div>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 700, color: "#CE1010" }}>One </span>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 400, color: "#5d5d5d" }}>breach</span>
          </div>

          <div>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 700, color: "#CE1010" }}>One </span>
            <span className="sm:text-[105px] text-[50px]" style={{ fontFamily: "'Inter',sans-serif", fontWeight: 400, color: "#5d5d5d" }}>bad experience.</span>
          </div>

          <div style={{ marginTop: 28 }}>
            <p style={{ fontSize: isMobile ? "15px" : "20px", color: "#343434", lineHeight: 1.6, margin: 0 }}>
              is all it takes to undo years of hard-earned customer confidence.
            </p>
          </div>
        </div>

        {/* ── Ghost annotation 1 — scrolls upward continuously ───────── */}
        {!isMobile && (
          <div style={{
            position: "absolute",
            left: "22%",
            top: "50%",                         // anchor at vertical centre
            zIndex: 10,
            pointerEvents: "none",
            background: "rgba(243,242,242,0.55)",
            backdropFilter: "blur(12px)",
            WebkitBackdropFilter: "blur(12px)",
            borderRadius: 8,
            padding: "16px 22px",
            width: 390,
            opacity: ghost1Opacity,
            // ── Key: scroll-driven upward movement, no transition so it tracks instantly ──
            transform: `translateY(${ghost1Y}px)`,
            transition: "none",
          }}>
            <p style={{ fontSize: 14, color: "#343434", lineHeight: 1.7, fontFamily: "'Inter',sans-serif", margin: 0 }}>
              When speed and scale take priority, due diligence
              slips and blind spots widen. That's exactly what is
              happening in the gig economy today.
            </p>
          </div>
        )}

        {/* ── Ghost annotation 2 — scrolls upward, offset timing ──────── */}
        {!isMobile && (
          <div style={{
            position: "absolute",
            right: "10%",
            top: "50%",                         // anchor at vertical centre
            zIndex: 10,
            pointerEvents: "none",
            background: "rgba(243,242,242,0.55)",
            backdropFilter: "blur(12px)",
            WebkitBackdropFilter: "blur(12px)",
            borderRadius: 8,
            padding: "16px 22px",
            width: 390,
            opacity: ghost2Opacity,
            transform: `translateY(${ghost2Y}px)`,
            transition: "none",
          }}>
            <p style={{ fontSize: 14, color: "#343434", lineHeight: 1.7, fontFamily: "'Inter',sans-serif", margin: 0 }}>
              Identity swaps, impersonation, and hidden criminal
              histories do more than disrupt operations. They put
              safety, credibility, and customer trust at risk.
            </p>
          </div>
        )}

        {/* ── Mobile: two annotations always visible, stacked ─────────── */}
        {isMobile && (
          <>
            <div style={{
              position: "absolute", top: "8%", left: "5%", right: "5%",
              zIndex: 10, pointerEvents: "none",
              background: "rgba(243,242,242,0.60)",
              backdropFilter: "blur(12px)", WebkitBackdropFilter: "blur(12px)",
              borderRadius: 8, padding: "12px 16px", opacity: 1,
            }}>
              <p style={{ fontSize: 13, color: "#343434", lineHeight: 1.65, fontFamily: "'Inter',sans-serif", margin: 0 }}>
                When speed and scale take priority, due diligence slips and blind spots widen.
              </p>
            </div>

            <div style={{
              position: "absolute", bottom: "5%", left: "5%", right: "5%",
              zIndex: 10, pointerEvents: "none",
              background: "rgba(243,242,242,0.60)",
              backdropFilter: "blur(12px)", WebkitBackdropFilter: "blur(12px)",
              borderRadius: 8, padding: "12px 16px", opacity: 1,
            }}>
              <p style={{ fontSize: 13, color: "#343434", lineHeight: 1.65, fontFamily: "'Inter',sans-serif", margin: 0 }}>
                Identity swaps and hidden criminal histories put safety, credibility, and customer trust at risk.
              </p>
            </div>
          </>
        )}

      </div>
    </div>
  );
}
